  "Order": "Ọ̀dà",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "Ìdánilójú apá kọ̀ọ̀kan wà lórí àmì rẹ̀ àti ìwé-owó rẹ̀; mú nọ́mbà ọ̀dà wá pẹ̀lú apá náà.",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "Àtúnṣe ní ìdánilójú láti ọjọ́ tí o gba fóònù rẹ. Mú tíkẹ́ẹ̀tì yìí wá.",
