  "Approved. Sign in and the shop shows your trade price on every part.": "Ti fọwọ́sí. Wọlé, o máa rí iye ìṣòwò rẹ lórí apá kọ̀ọ̀kan.",
  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "A ń dáhùn nípasẹ̀ ímeèlì àti WhatsApp, nígbà púpọ̀ láàrin ọjọ́ iṣẹ́ kan. Wọlé pẹ̀lú ímeèlì kan náà láti rí èsì níbí.",
