  "Chat with our team. Open WhatsApp on this device, or scan the code with your phone.": "Bá ẹgbẹ́ wa sọ̀rọ̀. Ṣí WhatsApp lórí ẹ̀rọ yìí tàbí ṣe àyẹ̀wò kóòdù pẹ̀lú fóònù rẹ.",
  "Add our number in WeChat and send us a message. We reply in Arabic, English and Chinese.": "Ṣàfikún nọ́mbà wa sí WeChat kí o sì kọ sí wa. A ń dáhùn ní Lárúbáwá, Gẹ̀ẹ́sì àti Ṣáínà.",
  "Chat with us": "Bá wa sọ̀rọ̀",
