  "Levels": "Ìpele",
  "IN STOCK · DEIRA": "WÀ NÍ ỌJÀ · DEIRA",
  "Screens, batteries, cameras, flex and more, tested before they ship.": "Ìbòjú, bátìrì, kámẹ́rà, flex àti bẹ́ẹ̀ bẹ́ẹ̀ lọ, a dán wọn wò kí a tó fi ránṣẹ́.",
  'WORLDWIDE SHIPPING': 'ÌFIRÁNṢẸ́ KÁRÍ AYÉ',
  'to your door.': 'dé ẹnu ọ̀nà rẹ.',
  'We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.': 'A ń fi àwọn ẹ̀yà ara ránṣẹ́ lọ́sọ̀ọ̀sẹ̀ sí àwọn ṣọ́ọ̀bù àtúnṣe àti oníṣòwò ní Àárín Gbùngbùn Ìlà Oòrùn, Áfíríkà, Yúróòpù àti Éṣíà: láti ilẹ̀kùn dé ilẹ̀kùn pẹ̀lú àwọn alábàáṣiṣẹ́ wa, tàbí pẹ̀lú olùfiránṣẹ́ tìrẹ.',
  'Weekly': 'Lọ́sọ̀ọ̀sẹ̀',
  'departures': 'ìfiránṣẹ́',
  'Door to door': 'Ilẹ̀kùn dé ilẹ̀kùn',
  'tracked and insured': 'a ń tọpa rẹ̀, ó sì ní ìdánilójú',
  'Your shipper': 'Olùfiránṣẹ́ rẹ',
  'welcome too': 'a kí i káàbọ̀ pẹ̀lú',
  'WHERE WE SHIP': 'IBI TÍ A Ń FI RÁNṢẸ́ SÍ',
  'Pick a region, then tap a country to see how we get there and how long it takes.': 'Yan agbègbè kan, lẹ́yìn náà tẹ orílẹ̀-èdè kan láti rí bí a ṣe ń dé ibẹ̀ àti bí ó ti pẹ́ tó.',
  'Tap a country for times': 'Tẹ orílẹ̀-èdè fún àkókò',
  'Get a quote': 'Gba ìdíyelé',
  'Same day to four weeks: you choose.': 'Láti ọjọ́ kan náà dé ọ̀sẹ̀ mẹ́rin: ìwọ ló yàn.',
  'Every way we ship, on one line. Urgent parts fly; big orders sail.': 'Gbogbo ọ̀nà tí a ń gbà fi ránṣẹ́, ní ìlà kan. Àwọn ẹ̀yà kíákíá ń fò; àwọn ìbéèrè ńlá ń lọ lójú omi.',
  'Collect in Deira': 'Gbà á ní Deira',
  'You or your agent picks it up at our counter, same day.': 'Ìwọ tàbí aṣojú rẹ yóò gbà á ní káńtà wa, lọ́jọ́ kan náà.',
  'Express courier': 'Kúríà kíákíá',
  'Door to door with DHL, UPS, FedEx or Aramex. Urgent parts.': 'Ilẹ̀kùn dé ilẹ̀kùn pẹ̀lú DHL, UPS, FedEx tàbí Aramex. Àwọn ẹ̀yà kíákíá.',
  'Road freight': 'Ìrìnnà ojú ọ̀nà',
  'By truck to Saudi Arabia, Oman and the Gulf.': 'Ní ọkọ̀ akẹ́rù lọ sí Saudi Arabia, Oman àti Gulf.',
  'Air cargo': 'Ẹrù ọkọ̀ òfuurufú',
  'Bulk orders to the main airports, best price per kilo.': 'Àwọn ìbéèrè ńlá sí àwọn pápákọ̀ òfuurufú pàtàkì, iye tó dára jù fún kìlò kan.',
  'About a week': 'Ó tó ọ̀sẹ̀ kan',
  'Sea freight': 'Ẹrù ojú omi',
  'Large orders by container, via Suez or East Africa.': 'Àwọn ìbéèrè ńlá nínú àpótí ẹrù, gba Suez tàbí Ìlà Oòrùn Áfíríkà.',
  'A commercial invoice and packing list go with every shipment.': 'Ìwé owó ìṣòwò àti àkójọ ẹrù ń bá gbogbo ìfiránṣẹ́ lọ.',
  'Duties and taxes are paid by the receiver on arrival, unless we agree otherwise.': 'Olùgbà ló ń san owó orí àti owó ẹ̀tọ́ nígbà tí ó bá dé, àyàfi tí a bá fohùn ṣọ̀kan mìíràn.',
  'Some routes need the importer’s company registration for clearance; we tell you before we ship.': 'Àwọn ọ̀nà kan ń béèrè ìforúkọsílẹ̀ ilé-iṣẹ́ olùkówọlé fún kọ́sítọ́mù; a ó sọ fún ọ kí a tó fi ránṣẹ́.',
  'Courier, air, road or sea: the best for your parts.': 'Kúríà, òfuurufú, ojú ọ̀nà tàbí òkun: èyí tó dára jù fún ẹ̀yà ara rẹ.',
  'It opens WhatsApp with your request, neatly laid out.': 'WhatsApp yóò ṣí pẹ̀lú ìbéèrè rẹ, tí a tò dáadáa.',
  'Shipping, time and paperwork, before you pay.': 'Ìfiránṣẹ́, àkókò àti ìwé, kí o tó sanwó.',
