  'You get one price': 'O gba iye kan',
  'You send the form': 'O fi fọ́ọ̀mù ránṣẹ́',
  'Send us your shipper': 'Rán olùfiránṣẹ́ rẹ sí wa',
  'weeks': 'ọ̀sẹ̀',
  'See every country': 'Wo gbogbo orílẹ̀-èdè',
  'Our home market: next-day to the Gulf, a few days to the Levant.': 'Ọjà ilé wa: ní ọjọ́ kejì sí Gulf, ọjọ́ díẹ̀ sí Levant.',
  'From London to Kyiv: express, air cargo or sea via Suez.': 'Láti London dé Kyiv: kíákíá, ẹrù òfuurufú tàbí òkun gba Suez.',
  'North, East and West Africa by courier, cargo or sea.': 'Àríwá, Ìlà Oòrùn àti Ìwọ̀ Oòrùn Áfíríkà nípasẹ̀ kúríà, ẹrù tàbí òkun.',
  'India, Pakistan and the Caucasus, by air and by sea.': 'India, Pakistan àti Caucasus, ní òfuurufú àti lójú omi.',
  'week': 'ọ̀sẹ̀',
  'Air cargo and express, from Dubai.': 'Ẹrù òfuurufú àti kíákíá, láti Dubai.',
