  'Air freight from Dubai': 'Ẹrù òfuurufú láti Dubai',
  'Already have a cargo agent or a courier account? Send them to us. We pack your order, hand it over and share the paperwork.': 'Ṣé o ti ní aṣojú ẹrù tàbí àkáǹtì kúríà? Rán an sí wa. A ó di ìbéèrè rẹ, fà á lé e lọ́wọ́, a ó sì pín ìwé.',
