  'Door to door, by us': 'Ilẹ̀kùn dé ilẹ̀kùn, láti ọwọ́ wa',
  'Every part checked, packed for the trip.': 'A ṣàyẹ̀wò gbogbo ẹ̀yà, a dì í fún ìrìn àjò.',
