  'Pick your phone and see every repair we do for it: the part in each grade, the fitting fee and the total, before you come in.': 'Yan fóònù rẹ kí o rí gbogbo àtúnṣe: ẹ̀yà ní ìpele kọ̀ọ̀kan, owó ìfisí àti àpapọ̀, kí o tó wá.',
  'Every repair for the': 'Gbogbo àtúnṣe fún',
  'Part price + fitting fee = your total. Prices are samples; the bench confirms the final price before starting.': 'Iye ẹ̀yà + owó ìfisí = àpapọ̀ rẹ. Àpẹẹrẹ ni iye; a ó jẹ́rìí sí iye ìkẹyìn kí a tó bẹ̀rẹ̀.',
  'The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.': 'Owó náà ń tẹ̀lé iye ẹ̀yà. Onímọ̀ wa lè ṣàtúnṣe rẹ̀, yóò sì máa sọ fún ọ kí ó tó bẹ̀rẹ̀.',
