  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'Mo rí nọ́mbà IMEI lórí fọ́tò náà. Fi ránṣẹ́ sí ẹgbẹ́ lórí WhatsApp, wọn ó wá àwòṣe gangan.',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'Mo wò ó dáadáa ṣùgbọ́n mi ò lè ka àwòṣe kankan lórí fọ́tò yìí. Àwòrán Ètò → Nípa fóònù ló dára jù, tàbí kàn sọ àwòṣe fún mi.',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'Mo lè ka ọ̀rọ̀ lórí fọ́tò, ṣùgbọ́n mi ò rí àwòṣe lórí èyí. Gbìyànjú àmì àpótí, tàbí kọ àwòṣe náà, màá bójú tó ìyókù.',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'Fi bọ́tìnnì kámẹ́rà fi fọ́tò ránṣẹ́ sí mi: àwòrán Ètò → Nípa fóònù, tàbí àmì àpótí, ló dára jù. Màá ka àwòṣe fún ọ.',
  'Settings → About phone → Model.': 'Ètò → Nípa fóònù → Àwòṣe.',
  'Settings → About phone → All specs → Model.': 'Ètò → Nípa fóònù → Gbogbo àlàyé → Àwòṣe.',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'Tẹ *#06# fún IMEI kí o sì fi ránṣẹ́ sí wa: a ó wá àwòṣe gangan.',
  'Still about your': 'Ṣì nípa',
  'Tell me the part: screen, battery, camera or charging port.': 'Sọ ẹ̀yà náà fún mi: iboju, bátìrì, kámẹ́rà tàbí ihò ìgbàgbára.',
  'Sure, for which model?': 'Dájúdájú, fún àwòṣe wo?',
