  'Tap below for the map and directions.': 'Tẹ ìsàlẹ̀ fún máàpù àti ìtọ́sọ́nà.',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'Pe ilé ìtajà, fi ìfiránṣẹ́ ránṣẹ́ sí wa lórí WhatsApp tàbí WeChat, tàbí ímeèlì. Àwa ni @samelectronics.uae lórí Instagram, TikTok àti Facebook.',
  'Every part has a warranty that depends on the grade:': 'Ẹ̀yà kọ̀ọ̀kan ní ìdánilójú tó dá lórí ìpele:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'Sọ àwòṣe àti ẹ̀yà fún mi, bí “bátìrì A54” tàbí “iboju iPhone 13”, màá fi iye owó ìpele kọ̀ọ̀kan hàn ọ́.',
